func (r *masterRepoGorm) syncMongoMasterBindingsDatabase(ctx context.Context, connID int64, engineType string, defaultDatabase *string) {
	if !isDatabaseScopedRepoEngine(engineType) || defaultDatabase == nil {
		return
	}
	dbName := strings.TrimSpace(*defaultDatabase)
	if dbName == "" {
		return
	}
	mbTable := dbMasterBinding{}.TableName()
	_ = r.db.WithContext(ctx).Exec(
		`UPDATE `+mbTable+`
		    SET master_database = ?,
		        master_schema = ?,
		        physical_table_fqn = ? || '.' || master_table,
		        updated_at = CURRENT_TIMESTAMP
		  WHERE master_connection_id = ?`,
		dbName, dbName, dbName, connID,
	).Error
}

